sys_script_include.script:
var DevTools = Class.create();
DevTools.prototype = {
	initialize: function()
	{	
	},

	GetParentRecord: function(grRecord)
	{
		var IsFunction = x_snc_devtools.IsFunction;
		if (IsFunction(x_snc_datasilos.DevToolsGetParentRecord))
		{
			return DevToolsGetParentRecord(grRecord);
		}
		return false;
	},	

	GetLinkDirectory: function(linkdirectory)
	{
		var IsFunction = x_snc_devtools.IsFunction;
		if (IsFunction(x_snc_datasilos.DevToolsGetLinkDirectory))
		{
			return DevToolsGetLinkDirectory(linkdirectory);
		}
		return linkdirectory;
	},

	type: 'DevTools'
};
